} \end{equation}

Consider the Cech cochain $z = \left\{ z_{ijk} : U_{ijk} \to \widetilde{G} \right\}$ over the covering $\mathcal{U}$, where
\begin{equation}
z_{ijk} = \widetilde{g}_{ij} \widetilde{g}_{jk} \widetilde{g}_{ki}. \end{equation}

Let us prove that $\left\{ z_{ijk} \right\}$ is a \v Chech cocycle on $\mathcal{U}$.
First of all note that we have
\begin{equation}
\widetilde{g}_{ij} \widetilde{g}_{jk} = z_{ijk} \widetilde{g}_{ik} = \widetilde{g}_{ik} z_{ijk}. \end{equation}
Then
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) \widetilde{g}_{ki} = z_{ijk} \widetilde{g}_{ik} \widetilde{g}_{ki} = z_{ijk} \text{ and } \widetilde{g}_{ij} (\widetilde{g}_{jk} \widetilde{g}_{ki}) = \widetilde{g}_{ij} \widetilde{g}_{ji} z_{jki} = z_{jki}, \end{equation}
therefore $z_{ijk} = z_{kij} = z_{jki}$.
At the same time,
\begin{equation}
z_{ijk}^{-1} \widetilde{g}_{ik}^{-1} = \left( z_{ijk} \widetilde{g}_{ik} \right)^{-1} = \left( \widetilde{g}_{ij} \widetilde{g}_{jk} \right)^{-1} = \widetilde{g}_{kj} \widetilde{g}_{ji} = z_{kji} \widetilde{g}_{ki}, \end{equation}
hence follows that $z_{ijk}^{-1} = z_{kji} = z_{jik}$.
Moreover $z_{ijk} = 1$ if at least two indices coincide.
Thus $z = \left\{ z_{ijk} \right\}$ is a normalized cochain.
Now we have
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) (\widetilde{g}_{kj} \widetilde{g}_{jl}) = z_{ijk} \widetilde{g}_{ik} z_{kjl} \widetilde{g}_{kl} = z_{ijk} z_{kjl} z_{ikl} g_{il} \end{equation}
and
\begin{equation}
(\widetilde{g}_{ij} \widetilde{g}_{jk}) (\widetilde{g}_{kj} \widetilde{g}_{jl}) = (\widetilde{g}_{ij} (\widetilde{g}_{jk} (\widetilde{g}_{kj}) \widetilde{g}_{jl} = \widetilde{g}_{ij} \widetilde{g}_{jl} = z_{ijl} \widetilde{g}_{il}, \end{equation}
thus $z_{ijk} z_{kjl} z_{ikl} = z_{ijl}$, this implies
\begin{equation}
\delta z = z_{jkl} z_{ikl}^{-1} z_{ijl} z_{ijk}^{-1} = 0. \end{equation}

